/**
 * The shape of a client config.
 *
 * You normally do NOT edit this file. Edit `site.config.ts` instead:
 * your code editor uses these types to autocomplete fields and to underline
 * mistakes (for example a missing English text) in red.
 */

import type { FontName } from './fonts';

/** The two languages of the site. Portuguese (pt-PT) is the default. */
export type Locale = 'pt' | 'en';

/** Any text a visitor can read, in European Portuguese and in English. */
export interface LocalizedText {
  pt: string;
  en: string;
}

export type Weekday =
  | 'monday'
  | 'tuesday'
  | 'wednesday'
  | 'thursday'
  | 'friday'
  | 'saturday'
  | 'sunday';

/**
 * One opening period, in 24-hour time (`"HH:MM"`), Lisbon time.
 * A closing time earlier than the opening time means "after midnight",
 * e.g. `{ open: '19:00', close: '01:00' }`.
 */
export interface Shift {
  open: string;
  close: string;
}

/**
 * Opening hours for each day of the week.
 * - Closed all day: `[]`
 * - Open once: `[{ open: '08:00', close: '19:00' }]`
 * - Split shift (lunch + dinner): `[{ open: '12:00', close: '15:00' }, { open: '19:00', close: '22:30' }]`
 */
export type WeeklyHours = Record<Weekday, Shift[]>;

/** Dietary labels shown next to menu items. */
export type DietaryTag = 'vegetarian' | 'vegan' | 'gluten-free';

/**
 * A photo stored in `src/assets/images/<id>/` (where `<id>` is the config `id`).
 * `src` is only the file name, e.g. `'hero-sala.jpg'`.
 */
export interface Photo {
  src: string;
  /** Describes the photo for blind visitors and Google. Say what is in it. */
  alt: LocalizedText;
}

/** One price among several, e.g. "Meia dose" / "Dose" or "Copo" / "Garrafa". */
export interface PriceOption {
  label: LocalizedText;
  price: number;
}

export interface MenuItem {
  /** Short unique code, lowercase with dashes, e.g. `'bacalhau-a-bras'`. Used by `featuredDishes`. */
  id: string;
  name: LocalizedText;
  description?: LocalizedText;
  /**
   * Price in euros, VAT included: `12.5` is shown as "12,50 €".
   * For portions or sizes use a list:
   * `[{ label: { pt: 'Meia dose', en: 'Half portion' }, price: 9 }, { label: { pt: 'Dose', en: 'Full portion' }, price: 14 }]`
   * Leave it out when there is no fixed price (then use `priceNote`, e.g. "Preço do dia").
   */
  price?: number | PriceOption[];
  /** Small text after the price, e.g. `{ pt: '/kg', en: '/kg' }` or `{ pt: 'Preço do dia', en: 'Market price' }`. */
  priceNote?: LocalizedText;
  /** Optional photo. Required if the item is listed in `featuredDishes`. */
  photo?: Photo;
  tags?: DietaryTag[];
}

export interface MenuCategory {
  /** Lowercase, no spaces. Used in links such as `/menu/#peixe`. */
  id: string;
  name: LocalizedText;
  /** Optional line under the category title, e.g. "Ao almoço, de segunda a sexta". */
  note?: LocalizedText;
  items: MenuItem[];
}

export interface Review {
  /** First name only (privacy). */
  name: string;
  rating: 1 | 2 | 3 | 4 | 5;
  text: LocalizedText;
}

export interface ThemeColors {
  /** Main brand colour: buttons, links, the azulejo pattern. Must be dark enough for white text. */
  primary: string;
  /** Text colour on top of `primary` (usually white). */
  onPrimary: string;
  /** Second colour for small highlights: eyebrow titles, prices, stars. */
  accent: string;
  /** Page background. */
  background: string;
  /** Cards and boxes on top of the background. */
  surface: string;
  /** Main text colour. */
  text: string;
  /** Secondary text (descriptions, notes). Must still be readable. */
  muted: string;
  /** Dark sections such as the footer. White text is used on it. */
  dark: string;
}

export interface SiteConfig {
  /**
   * Short code for this client, lowercase with dashes, e.g. `'tasca-do-largo'`.
   * Photos must be in `src/assets/images/<id>/`. Also the value of SITE_CONFIG.
   */
  id: string;
  /** The final web address, without a trailing slash, e.g. `'https://www.tascadolargo.pt'`. */
  url: string;
  /** Shows a small "demo site / fictional business" line in the footer. Set to `false` for real clients. */
  isDemo: boolean;

  /** Business type for Google (schema.org). */
  businessType: 'Restaurant' | 'CafeOrCoffeeShop' | 'Bakery' | 'BarOrPub';
  /** Business name, the same in both languages. */
  name: string;
  /** One short sentence under the name in the hero. */
  tagline: LocalizedText;
  /** E.g. "Cozinha tradicional portuguesa". Shown above the name and sent to Google. */
  cuisine: LocalizedText;
  /** Rough price level for Google: '€', '€€' or '€€€'. */
  priceRange: '€' | '€€' | '€€€' | '€€€€';

  /** Browser tab title and Google description of the home page. Keep the description under ~155 characters. */
  seo: {
    title: LocalizedText;
    description: LocalizedText;
    /** Description of the menu page for Google. */
    menuDescription: LocalizedText;
  };

  /** Optional bar at the very top of every page, e.g. holidays. Remove it when it is no longer true. */
  notice?: LocalizedText;

  story: {
    title: LocalizedText;
    /** A few short paragraphs. Separate paragraphs with an empty line (`\n\n`). */
    text: LocalizedText;
  };

  address: {
    street: string;
    postalCode: string;
    city: string;
    /** Distrito / region, e.g. 'Coimbra'. */
    region: string;
    /** Two-letter country code. */
    country: 'PT';
  };
  /** GPS coordinates. In Google Maps: right-click the place → click the numbers to copy them. */
  geo: { lat: number; lng: number };
  map: {
    /** Show a Google map. It only loads after the visitor clicks (privacy). */
    embed: boolean;
    /** Map zoom, 15 to 18 works well. */
    zoom: number;
    /** Optional link to the business on Google Maps (share link). If empty, coordinates are used. */
    directionsUrl?: string;
  };

  contact: {
    /** Shown exactly as written, e.g. '+351 239 000 000'. */
    phone: string;
    /** WhatsApp number with country code, e.g. '+351 912 345 678'. Leave out if they don't use WhatsApp. */
    whatsapp?: string;
    email: string;
  };

  /** The header button ("Reservar mesa"). */
  booking: {
    /** Override the button text (default: "Reservar mesa" / "Book a table"). */
    label?: LocalizedText;
    /** Message that is pre-filled in WhatsApp. */
    message: LocalizedText;
    /** Use an online booking page (e.g. TheFork) instead of WhatsApp. */
    url?: string;
  };

  hours: WeeklyHours;
  /** Optional note under the opening hours, e.g. "Encerramos nos feriados". */
  hoursNote?: LocalizedText;

  /** Optional short text at the top of the menu page. */
  menuIntro?: LocalizedText;
  menu: MenuCategory[];
  /** 4 to 6 menu item ids to show on the home page. Each must have a photo. */
  featuredDishes: string[];

  reviews: {
    /** Average Google rating, e.g. 4.7. Update it from time to time. */
    rating: number;
    /** Number of Google reviews. */
    count: number;
    /** Link to the reviews on Google (Google Business Profile → "Read reviews" → share). */
    googleUrl: string;
    /** 3 to 6 reviews to show, copied from Google (first names only). */
    featured: Review[];
  };

  social: {
    instagram?: string;
    facebook?: string;
    tripadvisor?: string;
  };

  images: {
    /** Big photo at the top. Recommended 2400×1600 (landscape 3:2). */
    hero: Photo;
    /** 2 or 3 photos for the "about us" section. First: portrait 1200×1500; others: 1200×900. */
    about: Photo[];
    /** Image shown when the site is shared on WhatsApp/Facebook. 1200×630. File name only. */
    share: string;
    /** Optional logo (SVG or PNG, transparent background). If missing, the name is written in the heading font. */
    logo?: Photo & {
      /** Set to true if the logo already contains the business name (the name is then hidden visually). */
      includesName?: boolean;
    };
  };

  theme: {
    colors: ThemeColors;
    fonts: {
      /** Font for titles. See `src/config/fonts.ts` for the list. */
      heading: FontName;
      /** Font for normal text. */
      body: FontName;
    };
  };

  legal: {
    /** Legal company name, e.g. 'Tasca do Largo, Lda.' */
    companyName: string;
    /** NIF / NIPC (9 digits). */
    nif: string;
    /**
     * Only if the business is a member of a consumer arbitration centre (RAL),
     * e.g. `{ name: 'CIMAAL', url: 'https://www.consumoalgarve.pt' }`.
     */
    disputeResolution?: { name: string; url: string };
  };
}
